import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_S": 32},
        ),
    ],
    key=["S", "F"],
)
@triton.jit
def rms_norm_kernel(
    x_ptr,
    out_ptr,
    eps_ptr,
    S: tl.constexpr,
    F: tl.constexpr,
    stride_batch,
    stride_feat,
    BLOCK_S: tl.constexpr,
):
    pid = tl.program_id(0)
    num_s_blocks = tl.cdiv(S, BLOCK_S)
    batch_id = pid // num_s_blocks
    spatial_block_id = pid % num_s_blocks

    s_start = spatial_block_id * BLOCK_S
    s_offs = s_start + tl.arange(0, BLOCK_S)
    s_mask = s_offs < S

    batch_offset = batch_id.to(tl.int64) * stride_batch
    eps = tl.load(eps_ptr)

    sum_sq = tl.zeros((BLOCK_S,), dtype=tl.float32)
    for f in tl.static_range(F):
        x_offs = batch_offset + f * stride_feat + s_offs
        x_val = tl.load(x_ptr + x_offs, mask=s_mask, other=0.0)
        x_fp32 = x_val.to(tl.float32)
        sum_sq += x_fp32 * x_fp32

    mean_sq = sum_sq / F
    rms = tl.sqrt(mean_sq + eps.to(tl.float32))

    for f in tl.static_range(F):
        x_offs = batch_offset + f * stride_feat + s_offs
        x_val = tl.load(x_ptr + x_offs, mask=s_mask, other=0.0)
        out_val = x_val.to(tl.float32) / rms
        tl.store(out_ptr + x_offs, out_val.to(tl.bfloat16), mask=s_mask)


class Model(nn.Module):
    def __init__(self, num_features: int, eps: float = 1e-5):
        super(Model, self).__init__()
        self.num_features = num_features
        self.eps = eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.dtype != torch.bfloat16:
            x = x.to(torch.bfloat16)
        x = x.contiguous()

        B = x.shape[0]
        F = x.shape[1]
        spatial = 1
        for i in range(2, x.dim()):
            spatial *= x.shape[i]

        x_flat = x.view(B, F, spatial)
        out_flat = torch.empty_like(x_flat)

        stride_batch = F * spatial
        stride_feat = spatial

        eps_t = torch.tensor([self.eps], dtype=torch.float32, device=x.device)
        grid = lambda META: (B * triton.cdiv(spatial, META["BLOCK_S"]),)
        rms_norm_kernel[grid](
            x_flat,
            out_flat,
            eps_t,
            spatial,
            F,
            stride_batch,
            stride_feat,
        )

        return out_flat.view_as(x)
